1	// Package server implements the HTTP interface for the completion broker.
2	//
3	// Routes:
4	//
5	//	Runner-facing:
6	//	  POST /callback        Validate nonce + enqueue completion (→ 204 | 401 | 400)
7	//
8	//	Orchestrator-facing:
9	//	  POST /register        Register an in-flight handle (→ 204 | 409 | 400)
10	//	  POST /list-completed  Peek-and-lock completions (→ 200 JSON | 400)
11	//	  POST /ack             Commit consumption (→ 204 | 400)
12	//	  POST /nack            Return locked item to queue (→ 204 | 400)
13	package server
14	
15	import (
16		"encoding/json"
17		"errors"
18		"io"
19		"log"
20		"net/http"
21	
22		"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
23	)
24	
25	// Server is the HTTP broker server.
26	type Server struct {
27		st  store.Store
28		mux *http.ServeMux
29	}
30	
31	// New creates a Server backed by the given store and registers all routes.
32	func New(st store.Store) *Server {
33		s := &Server{st: st}
34		mux := http.NewServeMux()
35	
36		// Method-qualified patterns require Go 1.22+.
37		mux.HandleFunc("POST /callback", s.handleCallback)
38		mux.HandleFunc("POST /register", s.handleRegister)
39		mux.HandleFunc("POST /list-completed", s.handleListCompleted)
40		mux.HandleFunc("POST /ack", s.handleAck)
41		mux.HandleFunc("POST /nack", s.handleNack)
42		// Catch-all: 404.
43		mux.HandleFunc("/", s.handleNotFound)
44	
45		s.mux = mux
46		return s
47	}
48	
49	func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
50		s.mux.ServeHTTP(w, r)
51	}
52	
53	// ── Runner-facing ─────────────────────────────────────────────────────────────
54	
55	func (s *Server) handleCallback(w http.ResponseWriter, r *http.Request) {
56		var body struct {
57			Handle string               `json:"handle"`
58			Nonce  string               `json:"nonce"`
59			Result store.ExecutorResult `json:"result"`
60		}
61		if !decodeRequired(w, r, &body) {
62			return
63		}
64	
65		err := s.st.ValidateCallback(r.Context(), body.Handle, body.Nonce, body.Result)
66		switch {
67		case errors.Is(err, store.ErrUnknownHandle):
68			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unknown_handle"})
69		case errors.Is(err, store.ErrNonceMismatch):
70			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "nonce_mismatch"})
71		case err != nil:
72			log.Printf("callback internal error: %v", err)
73			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
74		default:
75			w.WriteHeader(http.StatusNoContent)
76		}
77	}
78	
79	// ── Orchestrator-facing ───────────────────────────────────────────────────────
80	
81	func (s *Server) handleRegister(w http.ResponseWriter, r *http.Request) {
82		var body struct {
83			Handle   string               `json:"handle"`
84			Nonce    string               `json:"nonce"`
85			Metadata store.HandleMetadata `json:"metadata"`
86		}
87		if !decodeRequired(w, r, &body) {
88			return
89		}
90	
91		err := s.st.Register(r.Context(), body.Handle, body.Nonce, body.Metadata)
92		switch {
93		case errors.Is(err, store.ErrAlreadyRegistered):
94			writeJSON(w, http.StatusConflict, map[string]string{"error": "already_registered"})
95		case err != nil:
96			log.Printf("register internal error: %v", err)
97			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
98		default:
99			w.WriteHeader(http.StatusNoContent)
100		}
101	}
102	
103	func (s *Server) handleListCompleted(w http.ResponseWriter, r *http.Request) {
104		// Defaults; allow empty body.
105		body := struct {
106			Max    int   `json:"max"`
107			LockMs int64 `json:"lock_ms"`
108		}{Max: 10, LockMs: 30_000}
109	
110		if r.ContentLength != 0 {
111			if err := json.NewDecoder(r.Body).Decode(&body); err != nil && !errors.Is(err, io.EOF) {
112				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_json"})
113				return
114			}
115		}
116		if body.Max <= 0 {
117			body.Max = 10
118		}
119		if body.LockMs <= 0 {
120			body.LockMs = 30_000
121		}
122	
123		completions, err := s.st.ListCompleted(r.Context(), body.Max, body.LockMs)
124		if err != nil {
125			log.Printf("list-completed internal error: %v", err)
126			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
127			return
128		}
129		if completions == nil {
130			completions = []store.Completion{}
131		}
132		writeJSON(w, http.StatusOK, completions)
133	}
134	
135	func (s *Server) handleAck(w http.ResponseWriter, r *http.Request) {
136		var body struct {
137			Handle string `json:"handle"`
138		}
139		if !decodeRequired(w, r, &body) {
140			return
141		}
142	
143		if err := s.st.Ack(r.Context(), body.Handle); err != nil {
144			log.Printf("ack internal error: %v", err)
145			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
146			return
147		}
148		w.WriteHeader(http.StatusNoContent)
149	}
150	
