372		ms := store.NewMemoryStoreWithClock(clock)
373		srv := newServerWithStore(ms)
374	
375		mustRegister(t, srv, "h1", "n1", testMeta("T1"))
376		mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})
