53			t.Fatalf("expected 1 completion, got %d", len(completions))
54		}
55		if completions[0].Handle != "h1" {
56			t.Fatalf("expected handle h1, got %s", completions[0].Handle)
57		}
58		if completions[0].Result.PrURL != "https://example.com/pr/1" {
59			t.Fatalf("unexpected pr_url: %s", completions[0].Result.PrURL)
