81		err := st.ValidateCallback(ctx, "ghost", "n", store.ExecutorResult{TerminalStatus: "in_review"})
82		if err != store.ErrUnknownHandle {
83			t.Fatalf("expected ErrUnknownHandle, got %v", err)
