86	
87	func TestRedisStore_NonceMismatch(t *testing.T) {
88		rdb := startMiniRedis(t)
89		st := store.NewRedisStore(rdb)
90		ctx := testCtx()
91	
92		if err := st.Register(ctx, "h1", "correct", testMetaR("T1")); err != nil {
93			t.Fatalf("register: %v", err)
