101	func TestRedisStore_PeekAndLock_LockedNotReturned(t *testing.T) {
102		rdb := startMiniRedis(t)
103		st := store.NewRedisStore(rdb)
104		ctx := testCtx()
105	
106		if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
107			t.Fatalf("register: %v", err)
108		}
109		if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
110			t.Fatalf("callback: %v", err)
111		}
112	
113		// First call locks.
114		items, err := st.ListCompleted(ctx, 10, 60_000)
115		if err != nil {
116			t.Fatalf("list 1: %v", err)
