package store_test

import (
	"context"
	"testing"
	"time"

	"github.com/redis/go-redis/v9"

	"github.com/alicebob/miniredis/v2"
	"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
)

// startMiniRedis starts an in-process Redis mock and returns a connected client.
func startMiniRedis(t *testing.T) *redis.Client {
	t.Helper()
	mr := miniredis.RunT(t)
	rdb := redis.NewClient(&redis.Options{Addr: mr.Addr()})
	t.Cleanup(func() { _ = rdb.Close() })
	return rdb
}

func testCtx() context.Context { return context.Background() }

func testMetaR(taskID string) store.HandleMetadata {
	return store.HandleMetadata{
		Kind:      "impl",
		TaskID:    taskID,
		FeatureID: "test-feature",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
}

func TestRedisStore_RegisterAndCallback(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "nonce1", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}

	result := store.ExecutorResult{TerminalStatus: "in_review", PrURL: "https://example.com/pr/1"}
	if err := st.ValidateCallback(ctx, "h1", "nonce1", result); err != nil {
		t.Fatalf("callback: %v", err)
	}

	completions, err := st.ListCompleted(ctx, 10, 30_000)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(completions) != 1 {
		t.Fatalf("expected 1 completion, got %d", len(completions))
	}
	if completions[0].Handle != "h1" {
		t.Fatalf("expected handle h1, got %s", completions[0].Handle)
	}
	if completions[0].Result.PrURL != "https://example.com/pr/1" {
		t.Fatalf("unexpected pr_url: %s", completions[0].Result.PrURL)
	}
}

func TestRedisStore_DuplicateRegister(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
		t.Fatalf("first register: %v", err)
	}
	if err := st.Register(ctx, "h1", "n2", testMetaR("T1")); err != store.ErrAlreadyRegistered {
		t.Fatalf("expected ErrAlreadyRegistered, got %v", err)
	}
}

func TestRedisStore_UnknownHandle(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	err := st.ValidateCallback(ctx, "ghost", "n", store.ExecutorResult{TerminalStatus: "in_review"})
	if err != store.ErrUnknownHandle {
		t.Fatalf("expected ErrUnknownHandle, got %v", err)
	}
}

func TestRedisStore_NonceMismatch(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "correct", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}
	err := st.ValidateCallback(ctx, "h1", "wrong", store.ExecutorResult{TerminalStatus: "in_review"})
	if err != store.ErrNonceMismatch {
		t.Fatalf("expected ErrNonceMismatch, got %v", err)
	}
}

func TestRedisStore_PeekAndLock_LockedNotReturned(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}
	if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
		t.Fatalf("callback: %v", err)
	}

	// First call locks.
	items, err := st.ListCompleted(ctx, 10, 60_000)
	if err != nil {
		t.Fatalf("list 1: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}

	// Second call should return nothing.
	items2, err := st.ListCompleted(ctx, 10, 60_000)
	if err != nil {
		t.Fatalf("list 2: %v", err)
	}
	if len(items2) != 0 {
		t.Fatalf("expected 0 items (still locked), got %d", len(items2))
	}
}

func TestRedisStore_Ack_ClearsEverything(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}
	if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
		t.Fatalf("callback: %v", err)
	}
	if _, err := st.ListCompleted(ctx, 1, 30_000); err != nil {
		t.Fatalf("list: %v", err)
	}
	if err := st.Ack(ctx, "h1"); err != nil {
		t.Fatalf("ack: %v", err)
	}

	// After ack: list should be empty and registry removed.
	items, err := st.ListCompleted(ctx, 10, 30_000)
	if err != nil {
		t.Fatalf("list after ack: %v", err)
	}
	if len(items) != 0 {
		t.Fatalf("expected empty queue after ack, got %d", len(items))
	}
	// Replay should fail with unknown_handle.
	err2 := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})
	if err2 != store.ErrUnknownHandle {
		t.Fatalf("expected ErrUnknownHandle after ack, got %v", err2)
	}
}

func TestRedisStore_Nack_UnlocksItem(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}
	if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
		t.Fatalf("callback: %v", err)
	}

	// Lock it.
	if _, err := st.ListCompleted(ctx, 1, 60_000); err != nil {
		t.Fatalf("list: %v", err)
	}

	// Nack.
	if err := st.Nack(ctx, "h1"); err != nil {
		t.Fatalf("nack: %v", err)
	}

	// Should be available again.
	items, err := st.ListCompleted(ctx, 1, 5_000)
	if err != nil {
		t.Fatalf("list after nack: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item after nack, got %d", len(items))
	}
}

func TestRedisStore_ReclaimExpired(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	if err := st.Register(ctx, "h1", "n1", testMetaR("T1")); err != nil {
		t.Fatalf("register: %v", err)
	}
	if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
		t.Fatalf("callback: %v", err)
	}

	// Lock for 1ms — expired almost immediately.
	if _, err := st.ListCompleted(ctx, 1, 1); err != nil {
		t.Fatalf("list: %v", err)
	}

	// Wait for lock to expire (real wall-clock, since RedisStore uses time.Now).
	time.Sleep(10 * time.Millisecond)

	// Reclaim.
	if err := st.ReclaimExpired(ctx); err != nil {
		t.Fatalf("reclaim: %v", err)
	}

	// Item should be available again.
	items, err := st.ListCompleted(ctx, 1, 5_000)
	if err != nil {
		t.Fatalf("list after reclaim: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item after reclaim, got %d", len(items))
	}
}

func TestRedisStore_MetadataPropagated(t *testing.T) {
	rdb := startMiniRedis(t)
	st := store.NewRedisStore(rdb)
	ctx := testCtx()

	meta := store.HandleMetadata{
		Kind:      "review-fix",
		Subkind:   "rebase",
		TaskID:    "T5",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
	if err := st.Register(ctx, "h1", "n1", meta); err != nil {
		t.Fatalf("register: %v", err)
	}
	if err := st.ValidateCallback(ctx, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"}); err != nil {
		t.Fatalf("callback: %v", err)
	}

	items, err := st.ListCompleted(ctx, 1, 30_000)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	if items[0].Metadata.Kind != "review-fix" {
		t.Fatalf("unexpected kind: %s", items[0].Metadata.Kind)
	}
	if items[0].Metadata.Subkind != "rebase" {
		t.Fatalf("unexpected subkind: %s", items[0].Metadata.Subkind)
	}
}

