// Package store defines the storage interface and types for the completion broker.
package store

import (
	"context"
	"errors"
)

// Sentinel errors returned by Store implementations.
var (
	ErrUnknownHandle     = errors.New("unknown_handle")
	ErrNonceMismatch     = errors.New("nonce_mismatch")
	ErrAlreadyRegistered = errors.New("already_registered")
)

// HandleMetadata mirrors the TypeScript HandleMetadata type in runtime/abi/src/types.ts.
type HandleMetadata struct {
	Kind      string `json:"kind"`
	Subkind   string `json:"subkind,omitempty"`
	TaskID    string `json:"task_id"`
	FeatureID string `json:"feature_id"`
	TenantID  string `json:"tenant_id,omitempty"`
	StartedAt string `json:"started_at"`
}

// TokenUsage mirrors ExecutorResult.token_usage.
type TokenUsage struct {
	Input  int `json:"input"`
	Output int `json:"output"`
}

// ExecutorResult mirrors the TypeScript ExecutorResult type in runtime/abi/src/types.ts.
type ExecutorResult struct {
	TerminalStatus    string      `json:"terminal_status"`
	TokenUsage        *TokenUsage `json:"token_usage,omitempty"`
	BlockedReason     string      `json:"blocked_reason,omitempty"`
	BlockedSuggestion string      `json:"blocked_suggestion,omitempty"`
	PrURL             string      `json:"pr_url,omitempty"`
	HandoverPath      string      `json:"handover_path,omitempty"`
}

// Completion is one item returned by Store.ListCompleted (peek-and-lock).
type Completion struct {
	Handle      string         `json:"handle"`
	Result      ExecutorResult `json:"result"`
	Metadata    HandleMetadata `json:"metadata"`
	LockedUntil *int64         `json:"locked_until,omitempty"` // unix ms
}

// Store is the storage abstraction for the completion broker.
// Both the Redis-backed production store and the in-memory test store implement this interface.
//
// Peek-and-lock semantics (equivalent to Redis Streams XPENDING + XCLAIM pattern):
//   - ListCompleted atomically marks returned items "locked" for lockMs milliseconds.
//   - A locked item not Ack'd within lockMs is returned to the queue by ReclaimExpired.
//   - Nack returns a locked item to the queue immediately.
type Store interface {
	// Register records a handle as in-flight before submit.
	Register(ctx context.Context, handle, nonce string, metadata HandleMetadata) error

	// ValidateCallback validates the nonce and enqueues the completion.
	// Returns ErrUnknownHandle or ErrNonceMismatch on validation failure.
	ValidateCallback(ctx context.Context, handle, nonce string, result ExecutorResult) error

	// ListCompleted atomically peek-and-locks up to max completions for lockMs.
	ListCompleted(ctx context.Context, max int, lockMs int64) ([]Completion, error)

	// Ack commits consumption: removes the handle from the queue and registry.
	Ack(ctx context.Context, handle string) error

	// Nack returns a locked completion to the queue immediately.
	Nack(ctx context.Context, handle string) error

	// ReclaimExpired returns items whose visibility-timeout lock has expired to the queue.
	// Equivalent to XPENDING + XCLAIM in the Redis Streams consumer group pattern.
	ReclaimExpired(ctx context.Context) error
}

