package store

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/redis/go-redis/v9"
)

// RedisStore implements Store using Redis.
//
// Data layout:
//
//	broker:reg:{handle}   — Hash: {nonce, metadata_json}
//	broker:item:{handle}  — Hash: {result_json, metadata_json}
//	broker:pending        — Sorted Set: member=handle, score=0 (unlocked) or lockUntilMs (locked)
//
// Peek-and-lock is implemented via a Lua script over the sorted set:
//   - Unlocked items have score 0 (always eligible: 0 ≤ now for any wall-clock now).
//   - After listCompleted: score = lockUntil (unix ms).
//   - After nack / reclaim: score reset to 0.
//
// This achieves the same semantics as Redis Streams + consumer groups (XPENDING + XCLAIM):
//   - XREADGROUP ... > ≡ listCompleted (atomic peek + mark locked)
//   - XACK ≡ Ack (remove from PEL)
//   - XCLAIM / XAUTOCLAIM ≡ ReclaimExpired (reset score to 0 for expired items)
//   - "nack" ≡ Nack (reset score to 0 immediately)
//
// The sorted-set approach was chosen over native Streams because it provides explicit
// lockMs control without requiring per-consumer PEL bookkeeping in a single-service topology.
type RedisStore struct {
	rdb *redis.Client
}

// NewRedisStore returns a RedisStore backed by the given Redis client.
func NewRedisStore(rdb *redis.Client) *RedisStore {
	return &RedisStore{rdb: rdb}
}

// key helpers
func regKey(handle string) string  { return "broker:reg:" + handle }
func itemKey(handle string) string { return "broker:item:" + handle }

const pendingKey = "broker:pending"

// peekAndLockScript atomically reads up to max unlocked items from the sorted set
// and marks them locked with score=lockUntil.
// KEYS[1] = pending key
// ARGV[1] = now (unix ms string)
// ARGV[2] = lockUntil (unix ms string)
// ARGV[3] = max (count string)
// Returns: list of handle strings.
const peekAndLockScript = `
local now       = tonumber(ARGV[1])
local lockUntil = tonumber(ARGV[2])
local max       = tonumber(ARGV[3])
local key       = KEYS[1]

-- Items with score 0 (unlocked) or score ≤ now (expired lock) are eligible.
local items = redis.call('ZRANGEBYSCORE', key, '-inf', now, 'LIMIT', 0, max)
for _, handle in ipairs(items) do
    redis.call('ZADD', key, lockUntil, handle)
end
return items
`

// reclaimScript atomically resets expired locks (score in [1, now]) back to 0.
// KEYS[1] = pending key
// ARGV[1] = now (unix ms string)
// Returns: number of reclaimed items.
const reclaimScript = `
local now = tonumber(ARGV[1])
local key = KEYS[1]
-- Score 0 = unlocked; score 1..now = expired lock; score > now = active lock.
local items = redis.call('ZRANGEBYSCORE', key, '1', now)
for _, handle in ipairs(items) do
    redis.call('ZADD', key, 0, handle)
end
return #items
`

func (s *RedisStore) Register(ctx context.Context, handle, nonce string, metadata HandleMetadata) error {
	metaJSON, err := json.Marshal(metadata)
	if err != nil {
		return fmt.Errorf("marshal metadata: %w", err)
	}

	// HSETNX is atomic; returns 0 if the key already exists.
	ok, err := s.rdb.HSetNX(ctx, regKey(handle), "nonce", nonce).Result()
	if err != nil {
		return fmt.Errorf("redis HSETNX: %w", err)
	}
	if !ok {
		return ErrAlreadyRegistered
	}
	return s.rdb.HSet(ctx, regKey(handle), "metadata_json", string(metaJSON)).Err()
}

func (s *RedisStore) ValidateCallback(ctx context.Context, handle, nonce string, result ExecutorResult) error {
	entry, err := s.rdb.HGetAll(ctx, regKey(handle)).Result()
	if err != nil {
		return fmt.Errorf("redis HGETALL: %w", err)
	}
	if len(entry) == 0 {
		return ErrUnknownHandle
	}

	expectedNonce := entry["nonce"]
	if subtle.ConstantTimeCompare([]byte(nonce), []byte(expectedNonce)) == 0 {
		return ErrNonceMismatch
	}

	resultJSON, err := json.Marshal(result)
	if err != nil {
		return fmt.Errorf("marshal result: %w", err)
	}

	pipe := s.rdb.TxPipeline()
	pipe.HSet(ctx, itemKey(handle), "result_json", string(resultJSON), "metadata_json", entry["metadata_json"])
	pipe.ZAdd(ctx, pendingKey, redis.Z{Score: 0, Member: handle})
	_, err = pipe.Exec(ctx)
	return err
}

func (s *RedisStore) ListCompleted(ctx context.Context, max int, lockMs int64) ([]Completion, error) {
	now := time.Now().UnixMilli()
	lockUntil := now + lockMs

	handles, err := s.rdb.Eval(ctx, peekAndLockScript, []string{pendingKey},
		now, lockUntil, max,
	).StringSlice()
	if err != nil {
		if errors.Is(err, redis.Nil) {
			return nil, nil
		}
		return nil, fmt.Errorf("peek-and-lock script: %w", err)
	}

	completions := make([]Completion, 0, len(handles))
	for _, handle := range handles {
		item, err := s.rdb.HGetAll(ctx, itemKey(handle)).Result()
		if err != nil || len(item) == 0 {
			continue
		}

		var result ExecutorResult
		if err := json.Unmarshal([]byte(item["result_json"]), &result); err != nil {
			continue
		}

		var metadata HandleMetadata
		if err := json.Unmarshal([]byte(item["metadata_json"]), &metadata); err != nil {
			continue
		}

		lu := lockUntil
		completions = append(completions, Completion{
			Handle:      handle,
			Result:      result,
			Metadata:    metadata,
			LockedUntil: &lu,
		})
	}
	return completions, nil
}

func (s *RedisStore) Ack(ctx context.Context, handle string) error {
	pipe := s.rdb.TxPipeline()
	pipe.ZRem(ctx, pendingKey, handle)
	pipe.Del(ctx, regKey(handle))
	pipe.Del(ctx, itemKey(handle))
	_, err := pipe.Exec(ctx)
	return err
}

func (s *RedisStore) Nack(ctx context.Context, handle string) error {
	// Reset score to 0 (unlock immediately); XX = only update if member exists.
	return s.rdb.ZAddArgs(ctx, pendingKey, redis.ZAddArgs{
		XX:      true,
		Members: []redis.Z{{Score: 0, Member: handle}},
	}).Err()
}

func (s *RedisStore) ReclaimExpired(ctx context.Context) error {
	now := time.Now().UnixMilli()
	_, err := s.rdb.Eval(ctx, reclaimScript, []string{pendingKey}, now).Int()
	if err != nil && !errors.Is(err, redis.Nil) {
		return fmt.Errorf("reclaim script: %w", err)
	}
	return nil
}

