// Package server implements the HTTP interface for the completion broker.
//
// Routes:
//
//	Runner-facing:
//	  POST /callback        Validate nonce + enqueue completion (→ 204 | 401 | 400)
//
//	Orchestrator-facing:
//	  POST /register        Register an in-flight handle (→ 204 | 409 | 400)
//	  POST /list-completed  Peek-and-lock completions (→ 200 JSON | 400)
//	  POST /ack             Commit consumption (→ 204 | 400)
//	  POST /nack            Return locked item to queue (→ 204 | 400)
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"

	"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
)

// Server is the HTTP broker server.
type Server struct {
	st  store.Store
	mux *http.ServeMux
}

// New creates a Server backed by the given store and registers all routes.
func New(st store.Store) *Server {
	s := &Server{st: st}
	mux := http.NewServeMux()

	// Method-qualified patterns require Go 1.22+.
	mux.HandleFunc("POST /callback", s.handleCallback)
	mux.HandleFunc("POST /register", s.handleRegister)
	mux.HandleFunc("POST /list-completed", s.handleListCompleted)
	mux.HandleFunc("POST /ack", s.handleAck)
	mux.HandleFunc("POST /nack", s.handleNack)
	// Catch-all: 404.
	mux.HandleFunc("/", s.handleNotFound)

	s.mux = mux
	return s
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mux.ServeHTTP(w, r)
}

// ── Runner-facing ─────────────────────────────────────────────────────────────

func (s *Server) handleCallback(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Handle string               `json:"handle"`
		Nonce  string               `json:"nonce"`
		Result store.ExecutorResult `json:"result"`
	}
	if !decodeRequired(w, r, &body) {
		return
	}

	err := s.st.ValidateCallback(r.Context(), body.Handle, body.Nonce, body.Result)
	switch {
	case errors.Is(err, store.ErrUnknownHandle):
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unknown_handle"})
	case errors.Is(err, store.ErrNonceMismatch):
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "nonce_mismatch"})
	case err != nil:
		log.Printf("callback internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
	default:
		w.WriteHeader(http.StatusNoContent)
	}
}

// ── Orchestrator-facing ───────────────────────────────────────────────────────

func (s *Server) handleRegister(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Handle   string               `json:"handle"`
		Nonce    string               `json:"nonce"`
		Metadata store.HandleMetadata `json:"metadata"`
	}
	if !decodeRequired(w, r, &body) {
		return
	}

	err := s.st.Register(r.Context(), body.Handle, body.Nonce, body.Metadata)
	switch {
	case errors.Is(err, store.ErrAlreadyRegistered):
		writeJSON(w, http.StatusConflict, map[string]string{"error": "already_registered"})
	case err != nil:
		log.Printf("register internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
	default:
		w.WriteHeader(http.StatusNoContent)
	}
}

func (s *Server) handleListCompleted(w http.ResponseWriter, r *http.Request) {
	// Defaults; allow empty body.
	body := struct {
		Max    int   `json:"max"`
		LockMs int64 `json:"lock_ms"`
	}{Max: 10, LockMs: 30_000}

	if r.ContentLength != 0 {
		if err := json.NewDecoder(r.Body).Decode(&body); err != nil && !errors.Is(err, io.EOF) {
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_json"})
			return
		}
	}
	if body.Max <= 0 {
		body.Max = 10
	}
	if body.LockMs <= 0 {
		body.LockMs = 30_000
	}

	completions, err := s.st.ListCompleted(r.Context(), body.Max, body.LockMs)
	if err != nil {
		log.Printf("list-completed internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}
	if completions == nil {
		completions = []store.Completion{}
	}
	writeJSON(w, http.StatusOK, completions)
}

func (s *Server) handleAck(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Handle string `json:"handle"`
	}
	if !decodeRequired(w, r, &body) {
		return
	}

	if err := s.st.Ack(r.Context(), body.Handle); err != nil {
		log.Printf("ack internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) handleNack(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Handle string `json:"handle"`
	}
	if !decodeRequired(w, r, &body) {
		return
	}

	if err := s.st.Nack(r.Context(), body.Handle); err != nil {
		log.Printf("nack internal error: %v", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal_error"})
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) handleNotFound(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusNotFound, map[string]string{"error": "not_found"})
}

// ── Helpers ───────────────────────────────────────────────────────────────────

// decodeRequired decodes JSON from r.Body into v; writes 400 and returns false on failure.
func decodeRequired(w http.ResponseWriter, r *http.Request, v any) bool {
	if err := json.NewDecoder(r.Body).Decode(v); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid_json"})
		return false
	}
	return true
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
		log.Printf("writeJSON encode error: %v", err)
	}
}

// Package server implements the HTTP interface for the completion broker.
//
// Routes:
//
//	Runner-facing:
//	  POST /callback        Validate nonce + enqueue completion (→ 204 | 401 | 400)
//
//	Orchestrator-facing:
//	  POST /register        Register an in-flight handle (→ 204 | 409 | 400)
//	  POST /list-completed  Peek-and-lock completions (→ 200 JSON | 400)
//	  POST /ack             Commit consumption (→ 204 | 400)
