func (s *Server) handleListCompleted(w http.ResponseWriter, r *http.Request) {
	// Defaults; allow empty body.
	body := struct {
		Max    int   `json:"max"`
		LockMs int64 `json:"lock_ms"`
	}{Max: 10, LockMs: 30_000}

	if r.ContentLength != 0 {
