package server_test

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/tiendv89/agent-workflow/runtime/broker/internal/server"
	"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
)

// ── helpers ───────────────────────────────────────────────────────────────────

func newServer() *server.Server {
	return server.New(store.NewMemoryStore())
}

func newServerWithStore(st store.Store) *server.Server {
	return server.New(st)
}

func post(srv http.Handler, path string, body any) *httptest.ResponseRecorder {
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			panic(err)
		}
	}
	req := httptest.NewRequest(http.MethodPost, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	return rr
}

func get(srv http.Handler, path string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodGet, path, nil)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	return rr
}

func getBody(t *testing.T, rr *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	var out map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&out); err != nil {
		t.Fatalf("decode body: %v", err)
	}
	return out
}

func mustRegister(t *testing.T, srv http.Handler, handle, nonce string, meta store.HandleMetadata) {
	t.Helper()
	rr := post(srv, "/register", map[string]any{
		"handle":   handle,
		"nonce":    nonce,
		"metadata": meta,
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("register failed: %d %s", rr.Code, rr.Body.String())
	}
}

func mustCallback(t *testing.T, srv http.Handler, handle, nonce string, result store.ExecutorResult) {
	t.Helper()
	rr := post(srv, "/callback", map[string]any{
		"handle": handle,
		"nonce":  nonce,
		"result": result,
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("callback failed: %d %s", rr.Code, rr.Body.String())
	}
}

func testMeta(taskID string) store.HandleMetadata {
	return store.HandleMetadata{
		Kind:      "impl",
		TaskID:    taskID,
		FeatureID: "test-feature",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
}

// ── protocol fixture conformance tests ───────────────────────────────────────
// These tests replay the JSON fixtures in runtime/broker-protocol/fixtures/
// and assert identical behaviour to InMemoryBrokerAdapter (TypeScript, T3).

func TestFixture_CallbackValid(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-abc123", "nonce-xyz789", store.HandleMetadata{
		Kind:      "impl",
		TaskID:    "T3",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "nonce-xyz789",
		"result": map[string]any{
			"terminal_status": "in_review",
			"pr_url":          "https://github.com/example/repo/pull/42",
		},
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d: %s", rr.Code, rr.Body.String())
	}
}

func TestFixture_CallbackUnknownHandle(t *testing.T) {
	srv := newServer()
	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-unknown",
		"nonce":  "nonce-any",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "unknown_handle" {
		t.Fatalf("expected error=unknown_handle, got %v", body["error"])
	}
}

func TestFixture_CallbackNonceMismatch(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-abc123", "correct-nonce", store.HandleMetadata{
		Kind:      "impl",
		TaskID:    "T3",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "wrong-nonce",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "nonce_mismatch" {
		t.Fatalf("expected error=nonce_mismatch, got %v", body["error"])
	}
}

func TestFixture_CallbackReplay(t *testing.T) {
	srv := newServer()
	// Register → callback → list → ack (removes registry) → replay.
	mustRegister(t, srv, "handle-abc123", "nonce-xyz789", testMeta("T3"))
	mustCallback(t, srv, "handle-abc123", "nonce-xyz789", store.ExecutorResult{TerminalStatus: "in_review"})

	// Ack the handle (removes from registry — replay should now return unknown_handle).
	post(srv, "/list-completed", map[string]any{"max": 1})
	post(srv, "/ack", map[string]any{"handle": "handle-abc123"})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-abc123",
		"nonce":  "nonce-xyz789",
		"result": map[string]any{"terminal_status": "in_review"},
	})
	if rr.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 on replay, got %d", rr.Code)
	}
	body := getBody(t, rr)
	if body["error"] != "unknown_handle" {
		t.Fatalf("expected error=unknown_handle, got %v", body["error"])
	}
}

func TestFixture_CallbackBlockedResult(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "handle-def456", "nonce-blocked", store.HandleMetadata{
		Kind:      "review-fix",
		Subkind:   "rebase",
		TaskID:    "T5",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	})

	rr := post(srv, "/callback", map[string]any{
		"handle": "handle-def456",
		"nonce":  "nonce-blocked",
		"result": map[string]any{
			"terminal_status":    "blocked",
			"blocked_reason":     "missing_tool",
			"blocked_suggestion": "Install required CLI tool in the container image.",
		},
	})
	if rr.Code != http.StatusNoContent {
		t.Fatalf("expected 204, got %d: %s", rr.Code, rr.Body.String())
	}
}

