func TestCallback_MalformedJSON(t *testing.T) {
	srv := newServer()
	req := httptest.NewRequest(http.MethodPost, "/callback", bytes.NewBufferString("not-json"))
	req.Header.Set("Content-Type", "application/json")
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d", rr.Code)
	}
}

func TestCallback_UnknownRoute(t *testing.T) {
	srv := newServer()
	req := httptest.NewRequest(http.MethodGet, "/unknown", nil)
	rr := httptest.NewRecorder()
	srv.ServeHTTP(rr, req)
	if rr.Code != http.StatusNotFound {
		t.Fatalf("expected 404, got %d", rr.Code)
	}
}

// ── register tests ────────────────────────────────────────────────────────────

func TestRegister_DuplicateHandle(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))

	rr := post(srv, "/register", map[string]any{
		"handle":   "h1",
		"nonce":    "n2",
		"metadata": testMeta("T1"),
	})
	if rr.Code != http.StatusConflict {
		t.Fatalf("expected 409 on duplicate, got %d", rr.Code)
	}
}

// ── list-completed tests ──────────────────────────────────────────────────────

func TestListCompleted_EmptyQueue(t *testing.T) {
	srv := newServer()
	rr := post(srv, "/list-completed", map[string]any{"max": 5})
	if rr.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rr.Code)
	}
	var items []any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 0 {
		t.Fatalf("expected empty list, got %d items", len(items))
	}
}

func TestListCompleted_ReturnsEnqueuedCompletion(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	rr := post(srv, "/list-completed", map[string]any{"max": 5})
	if rr.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", rr.Code)
	}
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	if items[0]["handle"] != "h1" {
		t.Fatalf("expected handle=h1, got %v", items[0]["handle"])
	}
}

func TestListCompleted_LockedItemNotReturnedAgain(t *testing.T) {
	srv := newServer()
	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	// First call locks the item.
	post(srv, "/list-completed", map[string]any{"max": 5, "lock_ms": 60000})
	// Second call should return nothing.
	rr := post(srv, "/list-completed", map[string]any{"max": 5, "lock_ms": 60000})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 0 {
		t.Fatalf("expected 0 items (still locked), got %d", len(items))
	}
}

func TestListCompleted_RespectsMaxOption(t *testing.T) {
	srv := newServer()
	for i := 0; i < 5; i++ {
		h := "h" + string(rune('0'+i))
		n := "n" + string(rune('0'+i))
		mustRegister(t, srv, h, n, testMeta("T"+string(rune('0'+i))))
		mustCallback(t, srv, h, n, store.ExecutorResult{TerminalStatus: "in_review"})
	}

	rr := post(srv, "/list-completed", map[string]any{"max": 2})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 2 {
		t.Fatalf("expected 2 items (max=2), got %d", len(items))
	}
}

func TestListCompleted_EmptyBodyUsesDefaults(t *testing.T) {
