func TestVisibilityTimeout_ReclaimExpiredReturnsItemToQueue(t *testing.T) {
	var tick int64 = 1000
	clock := func() int64 { return tick }
	ms := store.NewMemoryStoreWithClock(clock)
	srv := newServerWithStore(ms)

	mustRegister(t, srv, "h1", "n1", testMeta("T1"))
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	// Lock with 2s window.
	post(srv, "/list-completed", map[string]any{"max": 1, "lock_ms": 2000})

	// Advance clock past lock expiry.
	tick = 4000

	// Reclaim expired locks.
	if err := ms.ReclaimExpired(nil); err != nil {
		t.Fatalf("reclaim: %v", err)
	}

	// Item should be available again.
	rr := post(srv, "/list-completed", map[string]any{"max": 1})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item after reclaim, got %d", len(items))
	}
}

