func TestListCompleted_IncludesMetadata(t *testing.T) {
	srv := newServer()
	meta := store.HandleMetadata{
		Kind:      "review-fix",
		Subkind:   "rebase",
		TaskID:    "T5",
		FeatureID: "runtime-portable-architecture",
		StartedAt: "2026-01-01T00:00:00.000Z",
	}
	mustRegister(t, srv, "h1", "n1", meta)
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})

	rr := post(srv, "/list-completed", map[string]any{"max": 1})
	var items []map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&items); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(items) != 1 {
		t.Fatalf("expected 1 item, got %d", len(items))
	}
	m, ok := items[0]["metadata"].(map[string]any)
	if !ok {
		t.Fatalf("metadata missing or wrong type")
	}
	if m["kind"] != "review-fix" {
		t.Fatalf("expected kind=review-fix, got %v", m["kind"])
	}
	if m["subkind"] != "rebase" {
		t.Fatalf("expected subkind=rebase, got %v", m["subkind"])
	}
	if m["task_id"] != "T5" {
		t.Fatalf("expected task_id=T5, got %v", m["task_id"])
