// ── registry-size tests ───────────────────────────────────────────────────────

func registrySize(t *testing.T, srv http.Handler) int {
	t.Helper()
	rr := get(srv, "/registry-size")
	if rr.Code != http.StatusOK {
		t.Fatalf("registry-size: expected 200, got %d: %s", rr.Code, rr.Body.String())
	}
	var body map[string]any
	if err := json.NewDecoder(rr.Body).Decode(&body); err != nil {
		t.Fatalf("registry-size decode: %v", err)
	}
	v, ok := body["size"].(float64)
	if !ok {
		t.Fatalf("registry-size: missing or non-numeric 'size' field: %v", body)
	}
	return int(v)
}

func TestRegistrySize_Empty(t *testing.T) {
	srv := newServer()
	if n := registrySize(t, srv); n != 0 {
		t.Fatalf("expected 0, got %d", n)
	}
}

func TestRegistrySize_RegisterN_AckOne(t *testing.T) {
	srv := newServer()

	// Register 3 handles.
	for i := 0; i < 3; i++ {
		h := "h" + string(rune('1'+i))
		mustRegister(t, srv, h, "n"+string(rune('1'+i)), testMeta("T"+string(rune('1'+i))))
	}
	if n := registrySize(t, srv); n != 3 {
		t.Fatalf("expected 3, got %d", n)
	}

	// Post a callback for h1 so it can be acked.
	mustCallback(t, srv, "h1", "n1", store.ExecutorResult{TerminalStatus: "in_review"})
	post(srv, "/list-completed", map[string]any{"max": 1})
	post(srv, "/ack", map[string]any{"handle": "h1"})

	if n := registrySize(t, srv); n != 2 {
		t.Fatalf("expected 2 after ack, got %d", n)
	}
}

